static int root_actor(struct environment* env,int actor,int32_t* first,int32_t* matches,int32_t* failure){if(actor==0)return key_order(&env->bytes,&env->keys,env->n,INT32_MAX,&env->order,failure);return key_find(&env->old_bytes,&env->old_keys,&env->old,0,5,1,first,matches,failure);}
